package com.fittrack.auth; import org.springframework.stereotype.Component; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import javax.crypto.SecretKey; import java.time.*; import java.util.*; @Component public class JwtService { SecretKey key; Duration access; public JwtService(@org.springframework.beans.factory.annotation.Value("${app.jwt-secret}") String s,@org.springframework.beans.factory.annotation.Value("${app.access-ttl}") Duration t){key=Keys.hmacShaKeyFor(s.getBytes(java.nio.charset.StandardCharsets.UTF_8));access=t;} public String access(User u){return Jwts.builder().subject(u.getId().toString()).claim("email",u.getEmail()).claim("roles",u.getRoles()).issuedAt(Date.from(Instant.now())).expiration(Date.from(Instant.now().plus(access))).signWith(key).compact();} public String subject(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();} }
